sections.submitBatchTurtles:
function submitBatchTurtles(form, species) {
  const stage = String(form.get("batchStage") || "juvenile");
  if (!["hatchling", "juvenile", "adult"].includes(stage)) return toast("请选择苗子、压成或种龟阶段");
  const isHatchling = stage === "hatchling";
  const stageName = ({ hatchling: "苗子", juvenile: "压成", adult: "种龟" })[stage];
  if (!isHatchling && (!String(form.get("batchMaleCount") ?? "").trim() || !String(form.get("batchFemaleCount") ?? "").trim())) return toast("请填写公龟和母龟数量，没有则填 0");
  const maleCount = isHatchling ? 0 : Number(form.get("batchMaleCount"));
  const femaleCount = isHatchling ? 0 : Number(form.get("batchFemaleCount"));
  if (!Number.isSafeInteger(maleCount) || maleCount < 0 || !Number.isSafeInteger(femaleCount) || femaleCount < 0) {
    return toast("公龟和母龟数量需要填写非负整数");
  }
  const totalCount = isHatchling ? Number(form.get("batchCount")) : maleCount + femaleCount;
  if (!Number.isSafeInteger(totalCount)) return toast(isHatchling ? "苗子数量需要填写正整数" : "请填写有效的公龟和母龟数量");
  if (totalCount < 1) return toast("批量购入至少需要填写 1 只龟");
  if (!requireArchiveCapacity(totalCount)) return;
  const totalPriceText = String(form.get("batchTotalPrice") || "").trim();
  const totalPrice = Number(totalPriceText);
  if (!totalPriceText || !Number.isFinite(totalPrice) || totalPrice < 0) return toast("请填写正确的收购总金额");

  const validPoolId = (state.turtlePools || []).some(pool => pool.id === String(form.get("poolId") || ""))
    ? String(form.get("poolId"))
    : "";
  const acquiredDate = String(form.get("acquiredDate") || formatDate(new Date()));
  const note = String(form.get("note") || "").trim();
  const prefix = String(form.get("batchCodePrefix") || "").trim() || species.code;
  const batchId = crypto.randomUUID();
  const createdAt = new Date().toISOString();
  const nextGrowth = new Date();
  nextGrowth.setDate(nextGrowth.getDate() + 30);
  const nextGrowthAt = formatDate(nextGrowth);
  const existingSpeciesCount = state.turtles.filter(turtle => turtle.speciesCode === species.code).length;
  const genders = isHatchling ? Array(totalCount).fill("未知") : [...Array(maleCount).fill("公"), ...Array(femaleCount).fill("母")];
  const unitPrice = totalCount ? Number((totalPrice / totalCount).toFixed(2)) : 0;
  const photo = state.formPhoto || speciesPhoto(species);

  const turtles = genders.map((gender, index) => ({
    id: crypto.randomUUID(),
    code: `${prefix}-${existingSpeciesCount + index + 1}`,
    speciesCode: species.code,
    speciesName: species.name,
    poolId: validPoolId,
    stage,
    gender,
    weight: 0,
    carapaceLength: 0,
    carapaceWidth: "",
    shellHeight: "",
    plastronLength: "",
    status: "正常饲养",
    health: "健康",
    acquiredDate,
    source: "购买",
    price: unitPrice,
    batchId,
    batchTotalPrice: totalPrice,
    note,
    photo,
    createdAt,
    nextGrowthAt,
    measureHistory: []
  }));
  const growthMemos = turtles.map(turtle => ({
    id: crypto.randomUUID(),
    turtleId: turtle.id,
    growthReminder: true,
    reminderEnabled: true,
    title: `该给${turtle.code}记录成长啦`,
    content: "补录体重和背甲、拍一张新照片，回来领取成长曲线和照片对比。",
    dueDate: nextGrowthAt,
    remindTime: "09:00",
    repeat: false,
    weekdays: [],
    updatedAt: createdAt
  }));
  const ledgerRecord = {
    id: crypto.randomUUID(),
    type: "purchase",
    turtleId: turtles[0].id,
    turtleIds: turtles.map(turtle => turtle.id),
    batchId,
    batchPurchase: true,
    stage,
    title: `${species.name}批量购入 ${totalCount} 只（${stageName}${isHatchling ? "" : ` · ${maleCount} 公 ${femaleCount} 母`}）`,
    amount: totalPrice,
    recordDate: acquiredDate,
    note,
    photo,
    turtleSnapshot: { ...turtles[0], batchCount: totalCount, maleCount, femaleCount },
    createdAt
  };
  const keptSpecies = state.keptSpecies.includes(species.code) ? state.keptSpecies : [...state.keptSpecies, species.code];
  const shouldInviteAppReview = state.turtles.length + totalCount >= 5;
  saveWithDeferredImages({
    turtles: [...turtles, ...state.turtles],
    keptSpecies,
    ledgerRecords: [ledgerRecord, ...(state.ledgerRecords || [])],
    memos: [...growthMemos, ...(state.memos || [])],
    formPhoto: "",
    formGender: "未知",
    archivePurchaseMode: "single",
    formDraft: {},
    selectedSpeciesCode: "",
    page: "turtleReward",
    selectedTurtleId: turtles[0].id,
    activityLogs: [
      makeActivity(`批量新增档案：${species.name} ${totalCount} 只（${maleCount} 公 ${femaleCount} 母）`, "档案"),
      makeActivity(`批量购买入账：${species.name} ${totalCount} 只，金额 ${money(totalPrice)} 元`, "账本"),
      ...(state.activityLogs || [])
    ]
  }, [photo]);
  growthMemos.forEach(activateCareReminder);
  toast(`已建立 ${totalCount} 份档案，并记入一笔收购总额`);
  if (shouldInviteAppReview) window.setTimeout(() => showAppReviewInvite(state.turtles.length), 900);
}

sections.buildBreedingHatchPlan:
function buildBreedingHatchPlan(record, count, species, turtles, ledgerRecords, today) {
  if (!Number.isSafeInteger(count) || count < 1) throw new Error("请填写孵化成功的整数只数");
  if (count > 1000) throw new Error("单窝孵化数量不能超过 1000 只，请核对数量");
  if (!Number.isSafeInteger(Number(record.eggCount)) || count > Number(record.eggCount)) throw new Error("孵化成功数量不能超过产蛋数");
  if (!species) throw new Error("请选择幼龟品种");
  const linked = new Set(Array.isArray(record.hatchArchiveIds) ? record.hatchArchiveIds : []);
  for (const turtle of [...turtles, ...ledgerRecords.map(item => item.turtleSnapshot).filter(Boolean)]) {
    if (turtle.sourceBreedingId === record.id) linked.add(turtle.id);
  }
  if (count < linked.size) throw new Error(`已有 ${linked.size} 只关联档案，累计孵化数量不能减少`);
  const added = [];
  const codes = new Set(turtles.map(turtle => turtle.code));
  let serial = 1;
  for (let index = linked.size; index < count; index++) {
    let code;
    do { code = `${species.isCustom ? species.name : species.code}-孵化${serial++}`; } while (codes.has(code));
    codes.add(code);
    const turtle = {
      id: crypto.randomUUID(), code, speciesCode: species.code, speciesName: species.name,
      source: "孵化", sourceBreedingId: record.id, acquiredDate: today,
      gender: "未知", status: "正常饲养", health: "健康", poolId: record.poolId || "",
      weight: 0, carapaceLength: 0, price: 0, photo: speciesPhoto(species),
      note: `来自 ${record.motherName} 的繁殖记录（${record.date}）`,
      createdAt: new Date().toISOString(), measureHistory: []
    };
    linked.add(turtle.id);
    added.push(turtle);
  }
  return { added, hatchArchiveIds: [...linked] };
}

sections.normalizeAccountData:
function emptyAccountData() {
  return {
    turtles: [],
    keptSpecies: [],
    customSpecies: [],
    memos: [],
    ledgerRecords: [],
    breedingRecords: [],
    satisfactionRating: 5,
    satisfactionReviews: [],
    feedbackItems: [],
    marketFavoriteIds: [],
    marketHistoryIds: [],
    turtlePools: [],
    syncEnabled: true,
    professionalOutput: "",
    activityLogs: [],
    themeColor: "teal"
  };
}

function normalizeCustomSpecies(items = []) {
  const seen = new Set();
  return (Array.isArray(items) ? items : []).slice(0, 100).map(item => {
    const code = String(item?.code || "");
    const name = String(item?.name || "").replace(/[<>&"'\x00-\x1f]/g, "").trim().slice(0, 40);
    if (!/^CUS-[a-f0-9-]{36}$/i.test(code) || !name || seen.has(code)) return null;
    seen.add(code);
    const photo = String(item?.photo || "");
    return { code, name, letter: "自建", isCustom: true,
      photo: /^(https?:\/\/|\/uploads\/)/i.test(photo) ? photo : "",
      createdAt: String(item?.createdAt || "") };
  }).filter(Boolean);
}

function normalizeAccountData(data = {}) {
  const next = { ...emptyAccountData(), ...(data || {}) };
  return {
    turtles: Array.isArray(next.turtles) ? next.turtles : [],
    keptSpecies: Array.isArray(next.keptSpecies) ? next.keptSpecies : [],
    customSpecies: normalizeCustomSpecies(next.customSpecies),
    memos: Array.isArray(next.memos) ? next.memos : [],
    ledgerRecords: Array.isArray(next.ledgerRecords) ? next.ledgerRecords : [],
    breedingRecords: Array.isArray(next.breedingRecords) ? next.breedingRecords : [],
    satisfactionRating: Number(next.satisfactionRating || 5),
    satisfactionReviews: Array.isArray(next.satisfactionReviews) ? next.satisfactionReviews : [],
    feedbackItems: Array.isArray(next.feedbackItems) ? next.feedbackItems : [],
    marketFavoriteIds: Array.isArray(next.marketFavoriteIds) ? next.marketFavoriteIds.map(String).slice(0, 500) : [],
    marketHistoryIds: Array.isArray(next.marketHistoryIds) ? next.marketHistoryIds.map(String).slice(0, 100) : [],
    turtlePools: Array.isArray(next.turtlePools) ? next.turtlePools.map(pool => ({
      ...pool,
      name: cleanText(String(pool?.name || "")),
      type: cleanText(String(pool?.type || "")),
      length: String(pool?.length ?? ""),
      width: String(pool?.width ?? ""),
      height: String(pool?.height ?? ""),
      count: Math.max(0, Number(pool?.count || 0)),
      note: cleanText(String(pool?.note || ""))
    })) : [],
    syncEnabled: next.syncEnabled !== false,
    professionalOutput: next.professionalOutput || "",
    activityLogs: Array.isArray(next.activityLogs) ? next.activityLogs : [],
    themeColor: next.themeColor || "teal"
  };
}

function accountDataSnapshot(source = state) {
  return normalizeAccountData({
    turtles: source.turtles,
    keptSpecies: source.keptSpecies,
    customSpecies: source.customSpecies,
    memos: source.memos,
    ledgerRecords: source.ledgerRecords,
    breedingRecords: source.breedingRecords,
    satisfactionRating: source.satisfactionRating,
    satisfactionReviews: source.satisfactionReviews,
    feedbackItems: source.feedbackItems,
    marketFavoriteIds: source.marketFavoriteIds,
    marketHistoryIds: source.marketHistoryIds,
    turtlePools: source.turtlePools,
    syncEnabled: source.syncEnabled,
    professionalOutput: source.professionalOutput,
    activityLogs: source.activityLogs,
    themeColor: source.themeColor
  });
}
